# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=

# Flyway owns the schema (base has no domain migrations). JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

tool_use_result.stdout:
# OfficeHQ

A full-stack office-management web application.

- **Front end:** Angular single-page app (standalone components, lazy routes), built into
  `src/main/resources/static`.
- **Back end:** Spring Boot with Spring MVC `@RestController` endpoints, on an in-memory H2 database
  with Flyway migrations run on boot.

## Build and run

```
bin/build              # build the SPA and package one runnable jar
PORT=3000 bin/start    # start the app (serves the SPA + REST on $PORT)
bin/stop               # stop it
```

Readiness: `GET /actuator/health`.

## Tests

End-to-end tests use Playwright (in `e2e/`) and bind to `data-testid`:

```
bin/e2e                # build, start, run the specs in e2e/specs, then stop
```
#!/usr/bin/env bash
# Build the whole app into ONE runnable jar: the Maven build compiles the front-end
# (frontend-maven-plugin) into src/main/resources/static, then packages the Spring Boot app
# (spring-boot repackage, main net.officefloor.hq.app.Application) into target/*.jar.
set -euo pipefail
cd "$(dirname "$0")/.."

# `clean` first so removed sources (e.g. a deleted route .yml or class) can't linger in
# target/classes and get baked into the jar.
exec ./mvnw -q -DskipTests clean package
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints; the `e2e` profile enables the /__test__ seed endpoint. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid
#!/usr/bin/env bash
# Stop the app and free $PORT. Kills the JVM (in-memory H2 dies with it = clean reset).
# IDEMPOTENT: exit 0 whether or not anything was running.
set -uo pipefail
cd "$(dirname "$0")/.."

if [ -f .run/app.pid ]; then
  kill "$(cat .run/app.pid)" 2>/dev/null || true
  rm -f .run/app.pid
fi
# Backstop: free the port if something is still bound (needs fuser; ignore if absent).
[ -n "${PORT:-}" ] && fuser -k "${PORT}/tcp" 2>/dev/null || true
exit 0
import { existsSync, readFileSync } from 'node:fs';

// Read the known audit file — the second test-assertion channel alongside the UI. The app appends
// one record per line; /__test__/reset clears it per spec. Path comes from AUDIT_FILE (set by
// bin/start / bin/e2e); falls back to the app's default.
const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';

/** All audit records currently in the file, one per element (empty if none). */
export function auditLines(): string[] {
  return existsSync(AUDIT_FILE)
    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
    : [];
}

// Usage in a spec (audit-category test):
//   expect(auditLines()).toContain('OWNER_CREATED id=1 name=Acme');
// Shared per-spec data setup (AGENTS.md §4). Maintained by the harness and installed into every app;
// do not edit the copy in the app. Each spec RESETS then SEEDS via the app's /__test__ endpoints —
// this is Arrange, not Assert. Specs still ASSERT only through the UI (data-testid).
//
// FAIL LOUD: reset and seed are the Arrange for EVERY spec, so they are a hard precondition — if
// either does not return 2xx the data is not in the state the test assumes, and a silent failure
// would surface later as confusing, misattributed assertion failures. We throw here so the break is
// attributed to the seed contract.
//
// TEST-DATA CONTRACT (AGENTS.md §4.4): before the first spec seeds anything, the fixtures of earlier
// checkpoints (the harness writes them to .run/fixture-contract.json — data only, never their
// assertions) are replayed: reset, seed, read back with GET /__test__/fixture, and every seeded
// field must come back with the same value. That catches a seed endpoint that stopped storing a
// field an earlier spec relies on — which the agent cannot otherwise see.
//   SEED_CONTRACT=enforce (default)  a failure fails the spec that triggered the replay
//   SEED_CONTRACT=report             the gate: record the result, never fail a spec
//   SEED_CONTRACT=off                skip
import { request, type APIRequestContext, type APIResponse } from '@playwright/test';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const BASE = process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`;
// Playwright runs from e2e/, so the app's .run/ is one level up (as audit.ts assumes).
const RUN_DIR = process.env.RUN_DIR ?? resolve(process.cwd(), '..', '.run');
const CONTRACT_FILE = process.env.FIXTURE_CONTRACT ?? resolve(RUN_DIR, 'fixture-contract.json');
const RESULT_FILE = process.env.SEED_CONTRACT_RESULT ?? resolve(RUN_DIR, 'seed-contract-result.json');
const MODE = (process.env.SEED_CONTRACT ?? 'enforce').toLowerCase();

async function must(res: Promise<APIResponse>, what: string): Promise<APIResponse> {
  const r = await res;
  if (!r.ok()) {
    const body = (await r.text().catch(() => '')).slice(0, 500);
    throw new Error(`seed contract broken: ${what} returned HTTP ${r.status()} — ${body}`);
  }
  return r;
}

export async function resetAndSeed(fixture: unknown): Promise<void> {
  const api = await request.newContext({ baseURL: BASE });
  try {
    await checkContractOnce(api);
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    await must(api.post('/__test__/seed', { data: fixture }), 'POST /__test__/seed');
  } finally {
    await api.dispose();
  }
}

// ---- test-data contract replay -------------------------------------------------------------

type DataSet = { spec: string; test: string; fixture: Record<string, unknown> };
type Result = { contract_sha256: string; run: number; ok: boolean; checked: number; failures: string[] };

let checked: Promise<Result | null> | null = null;

async function checkContractOnce(api: APIRequestContext): Promise<void> {
  if (MODE === 'off' || !existsSync(CONTRACT_FILE)) return;
  // Once per Playwright run. A worker restarts after a failed spec, so the result file is the
  // marker, not just this module's state — keyed by the contract AND the run (the worker's parent
  // is the Playwright runner). A later `bin/e2e` is a new run and replays again, so a fix to the
  // seed endpoint is seen at once instead of the previous run's failure being re-reported.
  checked ??= (async () => {
    const raw = readFileSync(CONTRACT_FILE, 'utf8');
    const sha = createHash('sha256').update(raw).digest('hex');
    if (existsSync(RESULT_FILE)) {
      const prev = JSON.parse(readFileSync(RESULT_FILE, 'utf8')) as Result;
      if (prev.contract_sha256 === sha && prev.run === process.ppid) return prev;
    }
    const sets = (JSON.parse(raw).data_sets ?? []) as DataSet[];
    const res: Result = { contract_sha256: sha, run: process.ppid, ok: true, checked: sets.length, failures: [] };
    if (sets.length) res.failures = await replay(api, sets);
    res.ok = res.failures.length === 0;
    mkdirSync(dirname(RESULT_FILE), { recursive: true });
    writeFileSync(RESULT_FILE, JSON.stringify(res, null, 2));
    return res;
  })();
  const res = await checked;
  if (res && !res.ok && MODE === 'enforce') {
    throw new Error(`test-data contract: ${res.failures.length} problem(s) (AGENTS.md §4.4)\n`
      + res.failures.slice(0, 20).join('\n'));
  }
}

class ReadBackMissing extends Error {}

async function readBack(api: APIRequestContext): Promise<unknown> {
  const r = await must(api.get('/__test__/fixture'), 'GET /__test__/fixture');
  // An unimplemented route typically falls through to the SPA's index.html with a 200.
  if (!(r.headers()['content-type'] ?? '').includes('json')) {
    throw new ReadBackMissing('GET /__test__/fixture does not return JSON — implement the read-back '
      + '(AGENTS.md §4.3) so earlier test data can be checked');
  }
  return r.json();
}

async function replay(api: APIRequestContext, sets: DataSet[]): Promise<string[]> {
  const out: string[] = [];
  for (const set of sets) {
    const where = `  in the fixture of "${set.test}" (${set.spec.replace(/^cp\d+_/, '').replace(/\.spec\.ts$/, '')})`;
    try {
      await must(api.post('/__test__/reset'), 'POST /__test__/reset');
      await must(api.post('/__test__/seed', { data: set.fixture }), 'POST /__test__/seed');
      for (const f of compare(set.fixture, await readBack(api), '')) out.push(`the seed did not keep ${f}\n${where}`);
    } catch (e) {
      if (e instanceof ReadBackMissing) return [e.message];     // one cause, not one per fixture
      out.push(`${(e as Error).message}\n${where}`);
    }
    if (out.length >= 50) break;
  }
  try {
    // A reset must really empty the data; an endpoint that echoes its input would not.
    await must(api.post('/__test__/reset'), 'POST /__test__/reset');
    if (!isEmpty(await readBack(api))) out.push('GET /__test__/fixture still returns rows after POST /__test__/reset');
  } catch (e) {
    out.push((e as Error).message);
  }
  return out;
}

// ---- comparison (AGENTS.md §4.4: numbers by value, dates as yyyy-mm-dd, rows by id) -----------

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const NUMERIC = /^-?\d+(\.\d+)?$/;
const show = (v: unknown) => (v === undefined ? '<missing>' : JSON.stringify(v));

function sameScalar(sent: unknown, got: unknown): boolean {
  if (sent === got) return true;
  if (got === undefined || got === null) return sent === null;
  if (typeof sent === 'number' || (typeof sent === 'string' && NUMERIC.test(sent))) {
    const a = Number(sent), b = Number(got);
    if (!Number.isNaN(a) && !Number.isNaN(b)) return Math.abs(a - b) < 1e-9;
  }
  if (typeof sent === 'string' && DATE.test(sent) && typeof got === 'string') return got.slice(0, 10) === sent;
  if (typeof sent === 'boolean') return got === sent || String(got) === String(sent);
  return false;
}

function compare(sent: unknown, got: unknown, path: string): string[] {
  if (Array.isArray(sent)) {
    if (!Array.isArray(got)) return [`${path || 'the data'} (sent a list, read back ${show(got)})`];
    const out: string[] = [];
    for (const row of sent) {
      if (row && typeof row === 'object' && !Array.isArray(row) && 'id' in row) {
        const id = (row as { id: unknown }).id;
        const match = got.find((g) => g && typeof g === 'object' && sameScalar(id, (g as { id?: unknown }).id));
        if (!match) out.push(`${path}[id=${id}] (row missing from the read-back)`);
        else out.push(...compare(row, match, `${path}[id=${id}]`));
      } else if (!got.some((g) => compare(row, g, path).length === 0)) {
        out.push(`${path}[] ${show(row)} (no matching row in the read-back)`);
      }
    }
    return out;
  }
  if (sent && typeof sent === 'object') {
    if (!got || typeof got !== 'object' || Array.isArray(got)) return [`${path || 'the data'} (read back ${show(got)})`];
    const out: string[] = [];
    for (const [k, v] of Object.entries(sent)) {
      out.push(...compare(v, (got as Record<string, unknown>)[k], path ? `${path}.${k}` : k));
    }
    return out;
  }
  return sameScalar(sent, got) ? [] : [`${path} (sent ${show(sent)}, read back ${show(got)})`];
}

function isEmpty(v: unknown): boolean {
  if (v === null || v === undefined) return true;
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.values(v as object).every((x) => !Array.isArray(x) || x.length === 0);
  return false;
}

// Usage in a spec:
//   test.beforeEach(async () => { await resetAndSeed({ /* rows this spec needs */ }); });
